import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// GEMM kernel: C[M,N] += A[M,K] @ B[K,N]  (split-K, atomic accumulate)
// A is row-major (M,K): stride (K,1)
// B is row-major (K,N): viewed transposed as (N,K) with stride (1,N)
// C is row-major (M,N): stride (N,1)
template <typename T>
__device__ __forceinline__ void load_A_tile_vec4(const T* __restrict__ A, int K, int m_block_off, int k_tile, T* smem_buf) {
  // Vectorized global->shared load for A: A is row-major (M,K) with K
  // contiguous, so 4 consecutive K-elements can be fetched with a single
  // 16-byte float4 load per thread instead of 4 separate scalar loads,
  // cutting the number of load instructions/transactions on the A operand
  // by 4x. The shared-memory destination keeps its original
  // M-contiguous, K-padded (stride 17) layout used by the compute stage,
  // so each loaded float4 lane is scattered to its own padded slot.
  constexpr int BLK_K_PAD_A = 16 + 1;
  int tid = threadIdx.x;
  int m_local = tid >> 2;   // 0..63
  int kv = tid & 3;         // 0..3 (float4 group index within BLK_K=16)
  int k_base = k_tile * 16 + kv * 4;
  #pragma unroll
  for (int r = 0; r < 2; ++r) {
    int m = m_local + r * 64;
    int gm = m_block_off + m;
    const float4* src = reinterpret_cast<const float4*>(A + (size_t)gm * K + k_base);
    float4 v = *src;
    T* dst = smem_buf + m * BLK_K_PAD_A;
    dst[kv * 4 + 0] = v.x;
    dst[kv * 4 + 1] = v.y;
    dst[kv * 4 + 2] = v.z;
    dst[kv * 4 + 3] = v.w;
  }
}
template <typename T>
__global__ static void
gemm_device(int M, int N, int K,
            const T* __restrict__ A,
            const T* __restrict__ B,
            T* __restrict__ C,
            int k_tiles_per_block,
            int k_tiles_total)
{
  // Full tensors (logical views over global memory)
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(K, 1));      // (M,K)
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(N, K), make_stride(1, N));      // (N,K) transposed view of (K,N) row-major
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(N, 1));      // (M,N)

  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<16>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);

  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1, X, _1>{});   // (BLK_M, BLK_K, ktiles)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X, _1, _1>{});   // (BLK_N, BLK_K, ktiles)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1, _1, X>{});   // (BLK_M, BLK_N)

  // Pad the K-stride of A's shared-memory tile so that consecutive threads
  // writing consecutive K-elements during the gmem->smem copy land in
  // distinct shared-memory banks (stride 16 is a multiple of 32 banks,
  // causing a 16-way bank conflict on every A tile store without padding).
  constexpr int BLK_K_PAD = 16 + 1;
  // Pad B's smem row pitch (its K-stride) so that the K-stride is no
  // longer a multiple of 32 shared-memory banks (128 elements causes a
  // bank conflict on every access during the FMA compute stage below).
  // The padding (128 -> 132, still a multiple of 4) does not disturb the
  // contiguous N-mode used by the vectorized float4 gmem->smem copy.
  constexpr int BLK_N_PAD = 128 + 4;
  __shared__ T smemA[2][128 * BLK_K_PAD];
  __shared__ T smemB[2][16 * BLK_N_PAD];
  Tensor sA0 = make_tensor(make_smem_ptr(smemA[0]), make_shape(Int<128>{}, Int<16>{}), make_stride(Int<BLK_K_PAD>{}, Int<1>{}));
  Tensor sB0 = make_tensor(make_smem_ptr(smemB[0]), make_shape(Int<128>{}, Int<16>{}), make_stride(Int<1>{}, Int<BLK_N_PAD>{}));
  Tensor sA1 = make_tensor(make_smem_ptr(smemA[1]), make_shape(Int<128>{}, Int<16>{}), make_stride(Int<BLK_K_PAD>{}, Int<1>{}));
  Tensor sB1 = make_tensor(make_smem_ptr(smemB[1]), make_shape(Int<128>{}, Int<16>{}), make_stride(Int<1>{}, Int<BLK_N_PAD>{}));
  auto tA = make_layout(make_shape(Int<16>{}, Int<16>{}), make_stride(Int<16>{}, Int<1>{}));  // row-major thread layout: consecutive threads walk the K dim of A for coalesced gmem loads
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));
  Tensor tAgA = local_partition(gA, tA, threadIdx.x);
  Tensor tAsA0 = local_partition(sA0, tA, threadIdx.x);
  Tensor tAsA1 = local_partition(sA1, tA, threadIdx.x);
  // Vectorize B's global->shared copy: B's contiguous (unit-stride)
  // dimension is N, so pack 4 consecutive N-elements into a single
  // float4 load/store, cutting the number of memory transactions by 4x.
  // The element-wise views (sB0/sB1, used below for the FMA compute
  // stage) remain untouched and still alias the same shared memory.
  Tensor gB_vec  = recast<float4>(gB);
  Tensor sB0_vec = recast<float4>(sB0);
  Tensor sB1_vec = recast<float4>(sB1);
  auto tB_vec = make_layout(make_shape(Int<32>{}, Int<8>{}));
  Tensor tBgB  = local_partition(gB_vec,  tB_vec, threadIdx.x);
  Tensor tBsB0 = local_partition(sB0_vec, tB_vec, threadIdx.x);
  Tensor tBsB1 = local_partition(sB1_vec, tB_vec, threadIdx.x);
  Tensor tCsA0 = local_partition(sA0, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsB0 = local_partition(sB0, tC, threadIdx.x, Step<X, _1>{});
  Tensor tCsA1 = local_partition(sA1, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsB1 = local_partition(sB1, tC, threadIdx.x, Step<X, _1>{});
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1, _1>{});
  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);
  int k_tile_start = blockIdx.z * k_tiles_per_block;
  int k_tile_end   = min(k_tile_start + k_tiles_per_block, k_tiles_total);
  // Software-pipelined double-buffered main loop: prefetch the next k-tile's
  // global->shared copy while the GEMM computes on the currently resident
  // shared-memory buffer, overlapping global memory latency with compute.
  if (k_tile_start < k_tile_end) {
    load_A_tile_vec4<T>(A, K, blockIdx.x * 128, k_tile_start, smemA[0]);
    copy(tBgB(_, _, k_tile_start), tBsB0);
  }
  __syncthreads();
  int buf = 0;
  for (int k_tile = k_tile_start; k_tile < k_tile_end; ++k_tile) {
    int next_tile = k_tile + 1;
    if (buf == 0) {
      if (next_tile < k_tile_end) {
        load_A_tile_vec4<T>(A, K, blockIdx.x * 128, next_tile, smemA[1]);
        copy(tBgB(_, _, next_tile), tBsB1);
      }
      gemm(tCsA0, tCsB0, tCrC);
    } else {
      if (next_tile < k_tile_end) {
        load_A_tile_vec4<T>(A, K, blockIdx.x * 128, next_tile, smemA[0]);
        copy(tBgB(_, _, next_tile), tBsB0);
      }
      gemm(tCsA1, tCsB1, tCrC);
    }
    __syncthreads();
    buf ^= 1;
  }

  // Atomic accumulate into global C (multiple k-splits write to same tile)
  CUTE_UNROLL
  for (int i = 0; i < size<0>(tCrC); ++i) {
    CUTE_UNROLL
    for (int j = 0; j < size<1>(tCrC); ++j) {
      atomicAdd(&tCgC(i, j), tCrC(i, j));
    }
  }
}

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int K2 = (int)B.size(0);
  int N = (int)B.size(1);
  TORCH_CHECK(K == K2, "Inner dimensions must match");

  constexpr int BLK_M = 128;
  constexpr int BLK_N = 128;
  constexpr int BLK_K = 16;

  TORCH_CHECK(M % BLK_M == 0, "M must be divisible by ", BLK_M);
  TORCH_CHECK(N % BLK_N == 0, "N must be divisible by ", BLK_N);
  TORCH_CHECK(K % BLK_K == 0, "K must be divisible by ", BLK_K);

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C = torch::zeros({M, N}, A.options());

  const float* ptrA = A_c.data_ptr<float>();
  const float* ptrB = B_c.data_ptr<float>();
  float* ptrC = C.data_ptr<float>();

  int k_tiles_total = K / BLK_K;

  // Choose a split-K factor so we get enough blocks to occupy the GPU
  // when M,N are small relative to K.
  constexpr int SPLIT_K = 512;
  int k_tiles_per_block = (k_tiles_total + SPLIT_K - 1) / SPLIT_K;
  if (k_tiles_per_block < 1) k_tiles_per_block = 1;
  int grid_z = (k_tiles_total + k_tiles_per_block - 1) / k_tiles_per_block;

  dim3 block(256);
  dim3 grid(M / BLK_M, N / BLK_N, grid_z);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  gemm_device<float><<<grid, block, 0, stream>>>(
      M, N, K, ptrA, ptrB, ptrC, k_tiles_per_block, k_tiles_total);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE gemm launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

cute_gemm_ext = load_inline(
    name="cute_gemm_splitk_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix multiplication C = A @ B, implemented with a custom split-K CuTe
    GEMM kernel to efficiently handle the case of small M,N and very large K.
    """
    def __init__(self) -> None:
        super().__init__()
        self._ext = cute_gemm_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matmul(A.contiguous(), B.contiguous())

