import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// GEMM kernel: C[M,N] += A[M,K] @ B[K,N]  (split-K, atomic accumulate)
// A is row-major (M,K): stride (K,1)
// B is row-major (K,N): viewed transposed as (N,K) with stride (1,N)
// C is row-major (M,N): stride (N,1)
template <class TAVec, class TASmem>
__device__ __forceinline__ void copy_A_vec4(TAVec const& gA_slice, TASmem& sA_elem) {
  // gA_slice: per-thread (M_sub, 1) tensor of float4 (vectorized K-groups from gmem)
  // sA_elem:  per-thread (M_sub, 4) tensor of float (scattered into padded smem tile)
  CUTE_UNROLL
  for (int m = 0; m < size<0>(gA_slice); ++m) {
    float4 v = gA_slice(m, 0);
    sA_elem(m, 0) = v.x;
    sA_elem(m, 1) = v.y;
    sA_elem(m, 2) = v.z;
    sA_elem(m, 3) = v.w;
  }
}
template <typename T>
__global__ static void
gemm_device(int M, int N, int K,
            const T* __restrict__ A,
            const T* __restrict__ B,
            T* __restrict__ C,
            int k_tiles_per_block,
            int k_tiles_total)
