  // global->shared copy while the GEMM computes on the currently resident
  // shared-memory buffer, overlapping global memory latency with compute.
  if (k_tile_start < k_tile_end) {
    copy_A_vec4(tAgA_vec(_, _, k_tile_start), tAsA0e);
    copy(tBgB(_, _, k_tile_start), tBsB0);
