  __shared__ T smemA[2][128 * BLK_K_PAD];
  __shared__ T smemB[2][128 * 16];
  Tensor sA0 = make_tensor(make_smem_ptr(smemA[0]), make_shape(Int<128>{}, Int<16>{}), make_stride(Int<1>{}, Int<BLK_K_PAD>{}));
  Tensor sB0 = make_tensor(make_smem_ptr(smemB[0]), make_shape(Int<128>{}, Int<16>{}));
  Tensor sA1 = make_tensor(make_smem_ptr(smemA[1]), make_shape(Int<128>{}, Int<16>{}), make_stride(Int<1>{}, Int<BLK_K_PAD>{}));
  Tensor sB1 = make_tensor(make_smem_ptr(smemB[1]), make_shape(Int<128>{}, Int<16>{}));
  auto tA = make_layout(make_shape(Int<16>{}, Int<16>{}), make_stride(Int<16>{}, Int<1>{}));  // row-major thread layout: consecutive threads walk the K dim of A for coalesced gmem loads
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));
  Tensor tAgA = local_partition(gA, tA, threadIdx.x);
  Tensor tAsA0 = local_partition(sA0, tA, threadIdx.x);
  Tensor tAsA1 = local_partition(sA1, tA, threadIdx.x);
  // Vectorize B's global->shared copy: B's contiguous (unit-stride)
  // dimension is N, so pack 4 consecutive N-elements into a single
  // float4 load/store, cutting the number of memory transactions by 4x.
  // The element-wise views (sB0/sB1, used below for the FMA compute
  // stage) remain untouched and still alias the same shared memory.
  Tensor gB_vec  = recast<float4>(gB);
  Tensor sB0_vec = recast<float4>(sB0);
  Tensor sB1_vec = recast<float4>(sB1);
  auto tB_vec = make_layout(make_shape(Int<32>{}, Int<8>{}));
  Tensor tBgB  = local_partition(gB_vec,  tB_vec, threadIdx.x);
  Tensor tBsB0 = local_partition(sB0_vec, tB_vec, threadIdx.x);
  Tensor tBsB1 = local_partition(sB1_vec, tB_vec, threadIdx.x);
  Tensor tCsA0 = local_partition(sA0, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsB0 = local_partition(sB0, tC, threadIdx.x, Step<X, _1>{});
  Tensor tCsA1 = local_partition(sA1, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsB1 = local_partition(sB1, tC, threadIdx.x, Step<X, _1>{});
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1, _1>{});
  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);
  int k_tile_start = blockIdx.z * k_tiles_per_block;
  int k_tile_end   = min(k_tile_start + k_tiles_per_block, k_tiles_total);
  // Software-pipelined double-buffered main loop: prefetch the next k-tile's
  // global->shared copy while the GEMM computes on the currently resident
  // shared-memory buffer, overlapping global memory latency with compute.
  if (k_tile_start < k_tile_end) {
    copy(tAgA(_, _, k_tile_start), tAsA0);
    copy(tBgB(_, _, k_tile_start), tBsB0);
  }
  __syncthreads();
  int buf = 0;
  for (int k_tile = k_tile_start; k_tile < k_tile_end; ++k_tile) {
    int next_tile = k_tile + 1;
    if (buf == 0) {
      if (next_tile < k_tile_end) {
        copy(tAgA(_, _, next_tile), tAsA1);
        copy(tBgB(_, _, next_tile), tBsB1);
      }
      gemm(tCsA0, tCsB0, tCrC);
    } else {
      if (next_tile < k_tile_end) {
        copy(tAgA(_, _, next_tile), tAsA0);
        copy(tBgB(_, _, next_tile), tBsB0);
      }
      gemm(tCsA1, tCsB1, tCrC);
    }
    __syncthreads();
    buf ^= 1;
  }

  // Atomic accumulate into global C (multiple k-splits write to same tile)
  CUTE_UNROLL
  for (int i = 0; i < size<0>(tCrC); ++i) {
    CUTE_UNROLL
    for (int j = 0; j < size<1>(tCrC); ++j) {
      atomicAdd(&tCgC(i, j), tCrC(i, j));
    }
  }
}

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int K2 = (int)B.size(0);
  int N = (int)B.size(1);
  TORCH_CHECK(K == K2, "Inner dimensions must match");

  constexpr int BLK_M = 128;
  constexpr int BLK_N = 128;
  constexpr int BLK_K = 16;

  TORCH_CHECK(M % BLK_M == 0, "M must be divisible by ", BLK_M);
  TORCH_CHECK(N % BLK_N == 0, "N must be divisible by ", BLK_N);
  TORCH_CHECK(K % BLK_K == 0, "K must be divisible by ", BLK_K);

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C = torch::zeros({M, N}, A.options());

  const float* ptrA = A_c.data_ptr<float>();
  const float* ptrB = B_c.data_ptr<float>();
  float* ptrC = C.data_ptr<float>();

  int k_tiles_total = K / BLK_K;

  // Choose a split-K factor so we get enough blocks to occupy the GPU
  // when M,N are small relative to K.
  constexpr int SPLIT_K = 512;
  int k_tiles_per_block = (k_tiles_total + SPLIT_K - 1) / SPLIT_K;
  if (k_tiles_per_block < 1) k_tiles_per_block = 1;
  int grid_z = (k_tiles_total + k_tiles_per_block - 1) / k_tiles_per_block;

  dim3 block(256);
  dim3 grid(M / BLK_M, N / BLK_N, grid_z);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  gemm_device<float><<<grid, block, 0, stream>>>(
      M, N, K, ptrA, ptrB, ptrC, k_tiles_per_block, k_tiles_total);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE gemm launch failed: ", cudaGetErrorString(err));

  return C;
}
